INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (1,1,'cabecera','Cabecera de página','cabecera_pagina',10,1,'Voluntariado','Los amigos de León',NULL,'La visita del Santo Padre al Perú será una experiencia inolvidable, y queremos vivirla sirviendo, acogiendo y haciendo comunidad.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-08-20 09:58:35');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (2,1,'resumen','En treinta segundos','pasos_numerados',20,1,'En treinta segundos','Pasos para ser voluntario',NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-08-21 05:42:31');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (3,1,'servicios','Los seis servicios','tarjetas_icono',30,1,'Seis servicios','Hay un lugar para cada talento y cada corazón',NULL,'Necesitamos voluntarios en los siguientes servicios:',NULL,NULL,NULL,NULL,'{\"cierre\": [\"Seis servicios, una sola misión: servir con alegría.\", \"Porque encontrarnos con el Santo Padre también significa poner nuestros dones al servicio de los demás.\", \"¿Te animas a ser parte de esta experiencia?\"], \"grito\": \"¡El Perú te necesita!\", \"boton_texto\": \"Inscríbete ahora\", \"boton_url\": \"#inscripcion\"}',NULL,'2026-08-20 10:04:50');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (4,1,'proceso','Las tres fases','fases',40,1,'Tres fases','Conoce el proceso de selección',NULL,'Tres fases, en este orden. La numeración de aquí abajo no es adorno: marca una secuencia real.',NULL,NULL,NULL,NULL,NULL,1,'2026-08-24 16:38:59');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (5,1,'inscripcion','Formulario de inscripción','formulario',50,1,'Solo esta fase se hace por internet','Inscríbete como voluntario',NULL,NULL,NULL,NULL,NULL,NULL,'{\"ten_a_mano_titulo\": \"Ten a mano\", \"ten_a_mano\": [\"Tu <strong>DNI</strong>, ocho dígitos\", \"Tu <strong>nombre completo</strong>\", \"Tu <strong>fecha de nacimiento</strong>\", \"Tu <strong>departamento, provincia y distrito</strong>\", \"Tu <strong>dirección</strong>: calle o avenida y número\", \"Tu <strong>correo electrónico</strong> y tu <strong>número telefónico</strong>\", \"Tu <strong>talla de polo</strong>: S, M, L, XL o XXL\", \"La <strong>jurisdicción</strong> en la que quieres servir\", \"El <strong>servicio</strong> que prefieres, de los seis\"], \"nota\": \"El contacto de emergencia es opcional: puedes darlo más adelante. Y si te interrumpen, lo que hayas escrito se guarda en este navegador.\", \"ancla_rotulo\": \"Fase 01 · Solo por internet\", \"ancla_titulo\": \"Inscríbete como voluntario\", \"ancla_dato\": \"Nueve datos, unos cinco minutos\", \"consentimiento\": \"Autorizo el tratamiento de mis datos personales por parte de <strong>[RESPONSABLE POR CONFIRMAR]</strong> con la única finalidad de gestionar mi inscripción como voluntario del viaje apostólico, asignarme un servicio y comunicarme con mi contacto de emergencia si fuera necesario. Mis datos se conservarán hasta <strong>[PLAZO POR CONFIRMAR]</strong> y después se eliminarán. Puedo ejercer mis derechos de acceso, rectificación, cancelación y oposición escribiendo a <strong>[CORREO POR CONFIRMAR]</strong>.\"}',NULL,'2026-08-21 05:39:49');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (6,1,'despues','Después de enviar','texto_lectura',60,1,'Después de enviar','Y entonces, ¿qué pasa?',NULL,'<p>Enviar el formulario no es quedar seleccionado, y tampoco hace falta que hagas nada más por tu cuenta: <strong>a partir de aquí la organización te busca a ti</strong>.</p><p>Te escribirá al correo que hayas dejado para pedirte los documentos de la <strong>Fase 02</strong>.</p><p>Ya cerca de la visita llega la <strong>Fase 03</strong>: la confirmación oficial, el área de servicio que se te asigna y la entrega de credenciales.</p>',NULL,NULL,NULL,NULL,NULL,NULL,'2026-08-20 11:29:24');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (8,3,'cabecera','Cabecera de página','cabecera_pagina',10,1,'Agenda','Los días del encuentro',NULL,'El Papa León XIV estará en el Perú del 11 al 16 de noviembre de 2026. El programa detallado todavía no es público: aquí está todo lo que sí se sabe, y nada de lo que no.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
