INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (11,3,'suele-incluir-viaje','¿Qué suele incluir un viaje apostólico?','texto_apartados',40,1,'No es el programa peruano','¿Qué suele incluir un viaje apostólico?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (12,3,'como-cuando-anunciara','Cómo y cuándo se anunciará el programa','texto_lectura',50,1,'Oficina de Prensa de la Santa Sede','Cómo y cuándo se anunciará el programa',NULL,'El programa detallado de un viaje apostólico lo publica la Oficina de Prensa de la Santa Sede. Es la fuente primaria: hasta que un acto aparece ahí, no existe oficialmente. Suele difundirse algunas semanas antes del viaje, en un documento con cada acto, su hora local y su sede. En el Perú, la Conferencia Episcopal Peruana difunde y adapta esa información: condiciones de acceso, transporte, puntos de encuentro y las indicaciones de cada diócesis. Las cuatro jurisdicciones implicadas —Lima, Chiclayo, Cusco y Pucallpa— publicarán además sus propias instrucciones. Cuando eso ocurra, esta página ca',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
