INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (16,4,'titular-sitio','Titular del sitio','texto_lectura',20,1,NULL,'Titular del sitio',NULL,'Los datos de titularidad de este apartado los debe completar la organización antes de la publicación del sitio. Aparecen entre corchetes. Titular del sitio Denominación: [RAZÓN SOCIAL POR CONFIRMAR]. Domicilio: [DOMICILIO POR CONFIRMAR]. Registro: [DATOS REGISTRALES POR CONFIRMAR]. Correo de contacto: [CORREO POR CONFIRMAR]. Objeto Este sitio tiene una finalidad exclusivamente informativa y pastoral: dar a conocer el viaje apostólico de Su Santidad el Papa León XIV al Perú, previsto del 11 al 16 de noviembre de 2026, y canalizar la participación de los fieles como voluntarios o colaboradores. ',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (17,5,'cabecera','Cabecera de página','cabecera_pagina',10,1,'Quién recibe la visita','La Iglesia en el Perú',NULL,'La Conferencia Episcopal Peruana y las cuatro jurisdicciones eclesiásticas que acogen el viaje apostólico.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (18,5,'quien-organiza-visita','Quién organiza la visita','texto_lectura',20,1,'La Conferencia','Quién organiza la visita',NULL,'La Conferencia Episcopal Peruana reúne a los obispos de las diócesis, arquidiócesis, prelaturas y vicariatos apostólicos del país. Es el organismo que coordina la preparación del viaje en el Perú, difunde y adapta lo que publica la Santa Sede, y articula el trabajo de las cuatro jurisdicciones que reciben al Santo Padre. León XIV la conoce por dentro. Fue su segundo vicepresidente desde marzo de 2018, miembro de su Consejo Económico y presidente de la Comisión Episcopal de Cultura y Educación. En 2023 la propia Conferencia le concedió la Medalla de Oro de Santo Toribio de Mogrovejo. Los datos ',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
