INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (20,6,'cabecera','Cabecera de página','cabecera_pagina',10,1,'Organización del viaje','Contacto',NULL,'Cuéntanos qué necesitas y te respondemos. Si tu consulta es sobre el programa, quizá ya esté resuelta en las preguntas frecuentes.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
