INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (22,7,'cabecera','Cabecera de página','cabecera_pagina',10,1,'Legal','Cookies',NULL,'La respuesta corta: este sitio no usa cookies. La larga explica qué guarda tu navegador y por qué.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (23,7,'este-sitio-instala','Este sitio no instala cookies','texto_lectura',20,1,NULL,'Este sitio no instala cookies',NULL,'Este sitio no instala cookies Ni propias ni de terceros. No hay analítica, no hay píxeles de seguimiento, no hay publicidad y no hay perfilado. Por eso no verás un banner de consentimiento: no habría nada que consentir. Lo que sí guarda tu navegador El sitio usa el almacenamiento del navegador para dos cosas, ambas técnicas y ambas dentro de tu propio equipo. Este almacenamiento no se envía al servidor en cada petición, a diferencia de una cookie. 1. El borrador del formulario de voluntariado. Clave l14-inscripcion-borrador, en localStorage. Guarda lo que hayas escrito en el formulario para qu',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (24,8,'cabecera','Cabecera de página','cabecera_pagina',10,1,'Cómo ayudar','Con un donativo',NULL,'Los donativos se destinan a los trabajos organizativos y pastorales de la visita, y se gestionan con responsabilidad y transparencia.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (25,8,'todavia-canal-donativos','Todavía no hay canal de donativos abierto','texto_lectura',20,1,'Estado','Todavía no hay canal de donativos abierto',NULL,'Este sitio no tiene pasarela de pago y no la tendrá hasta que la organización defina la titularidad de la cuenta y el tratamiento fiscal de los aportes. Habilitar cobros antes de eso sería irresponsable. Cuando el canal esté abierto, aparecerá aquí con la cuenta oficial, el nombre exacto del titular y el procedimiento para pedir constancia del aporte. Desconfía de cualquier cuenta que circule antes de ese anuncio, aunque venga con el escudo y con fotos del Santo Padre. Si no está publicada en esta página o por la Conferencia Episcopal Peruana, no es oficial.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
