INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (28,9,'cabecera','Cabecera de página','cabecera_pagina',10,1,'267.º sucesor de Pedro','Cuarenta años de Perú',NULL,'Robert Francis Prevost llegó a Chulucanas en 1985 con treinta años. Salió del Perú en 2023 siendo ciudadano peruano y obispo de Chiclayo.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (29,9,'quien-leon-xiv','Quién es León XIV','texto_lectura',20,1,'En breve','Quién es León XIV',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (30,9,'raices-vocacion-agustiniana','Raíces y vocación agustiniana','texto_lectura',30,1,'1955 – 1984','Raíces y vocación agustiniana',NULL,'Nació en Chicago el 14 de septiembre de 1955, hijo de Louis Marius Prevost, de ascendencia francesa e italiana, y de Mildred Martínez, de ascendencia española. Tiene dos hermanos, Louis Martín y John Joseph. Estudió primero en el Seminario Menor de los Padres Agustinos y después en la Universidad de Villanova, en Pensilvania, donde se licenció en Matemáticas y cursó Filosofía en 1977. El 1 de septiembre de ese mismo año ingresó en el noviciado de la Orden de San Agustín en St. Louis, en la provincia de Nuestra Señora del Buen Consejo de Chicago. Hizo su primera profesión el 2 de septiembre de ',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (31,9,'misionero-formador-peru','Misionero y formador en el Perú','texto_lectura',40,1,'1985 – 1999','Misionero y formador en el Perú',NULL,'Se licenció en 1984 y al año siguiente, mientras preparaba su tesis doctoral, fue enviado a la misión agustiniana de Chulucanas, en Piura. Allí empezaron sus cuarenta años de Perú. En 1987 defendió su tesis sobre el papel del prior local en la Orden de San Agustín y fue nombrado director de Vocaciones y director de Misiones de su provincia agustiniana en Illinois. Al año siguiente volvió, esta vez a Trujillo, como director del proyecto de formación común para los aspirantes agustinos de los vicariatos de Chulucanas, Iquitos y Apurímac: el desierto, la selva y los Andes en una misma casa de for',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (32,9,'prior-general-obispo','De prior general a obispo de Chiclayo','texto_lectura',50,1,'1999 – 2023','De prior general a obispo de Chiclayo',NULL,'En 1999 fue elegido prior provincial de la provincia agustiniana de Chicago y, dos años y medio después, sus hermanos lo eligieron prior general de la Orden. Fue confirmado en 2007 para un segundo mandato. El 3 de noviembre de 2014 el Papa Francisco lo nombró administrador apostólico de la diócesis de Chiclayo y lo elevó a la dignidad episcopal como obispo titular de Sufar. Entró en la diócesis el 7 de noviembre y fue ordenado obispo el 12 de diciembre, festividad de Nuestra Señora de Guadalupe, en la catedral de Santa María. El 26 de septiembre de 2015 fue nombrado obispo de Chiclayo. En marz',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (33,9,'chiclayo-pontificado','De Chiclayo al pontificado','texto_lectura',60,1,'2023 – hoy','De Chiclayo al pontificado',NULL,'El 30 de enero de 2023 el Papa Francisco lo llamó a Roma como prefecto del Dicasterio para los Obispos y presidente de la Pontificia Comisión para América Latina, elevándolo al rango de arzobispo. En el consistorio del 30 de septiembre de ese año fue creado cardenal, con la diaconía de Santa Mónica, de la que tomó posesión en enero de 2024. El 6 de febrero de 2025 fue promovido al orden de los cardenales obispos, con el título suburbicario de Albano. Durante la última hospitalización del Papa Francisco presidió, el 3 de marzo, el rosario por la salud del Pontífice en la plaza de San Pedro. El ',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (34,9,'escudo-lema','El escudo y el lema','texto_lectura',70,1,'Heráldica','El escudo y el lema',NULL,'El escudo está dividido diagonalmente en dos sectores. La parte superior tiene fondo azul y presenta un lirio blanco. La inferior, sobre fondo claro, lleva la imagen que recuerda a la Orden de San Agustín: un libro cerrado sobre el que descansa un corazón traspasado por una flecha. Esa imagen evoca la conversión de san Agustín, que él mismo explicó con las palabras «Vulnerasti cor meum verbo tuo»: has traspasado mi corazón con tu Palabra. El lema, «In Illo uno unum», procede de un sermón de san Agustín, la Exposición del Salmo 127, y significa que aunque los cristianos seamos muchos, en el úni',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (35,9,'magisterio-hasta-hoy','Su magisterio hasta hoy','texto_lectura',80,1,'Documentos','Su magisterio hasta hoy',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (36,10,'cabecera','Cabecera de página','cabecera_pagina',10,1,'Del 11 al 16 de noviembre','En directo',NULL,'No hace falta estar en la explanada. Aquí estarán los enlaces de cada transmisión en cuanto existan.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (37,10,'todavia-enlaces','Todavía no hay enlaces','texto_lectura',20,1,'Estado','Todavía no hay enlaces',NULL,'Los viajes apostólicos se transmiten habitualmente por los medios de comunicación de la Santa Sede y por las emisoras y los canales de la Iglesia en el país que recibe la visita. Es razonable esperar que así sea también aquí, pero ningún enlace concreto está confirmado. En cuanto se publique el programa, esta página tendrá una fila por acto, con su hora en horario de Lima y el enlace directo a la transmisión. Mientras tanto, no publicamos nada que no podamos sostener.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (38,10,'tres-maneras-seguirlo','Tres maneras de seguirlo','texto_lectura',30,1,'Mientras tanto','Tres maneras de seguirlo',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (39,10,'avisame-cuando-haya','Avísame cuando haya transmisión','texto_lectura',40,1,'Aviso','Avísame cuando haya transmisión',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (40,11,'cabecera','Cabecera de página','cabecera_pagina',10,1,'Para quien va a ir','Guía del peregrino',NULL,'Lo que sí puedes preparar desde ya, y lo que habrá que esperar. Ninguna de estas indicaciones sustituye a las de tu diócesis.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (41,11,'esta-confirmado','Qué está confirmado y qué no','texto_lectura',20,1,'Antes de nada','Qué está confirmado y qué no',NULL,'Esta guía no inventa logística. Lo que encontrarás aquí son las cosas que puedes preparar sin saber todavía dónde ni a qué hora será cada acto: el equipaje, la salud, los niños, la accesibilidad y, sobre todo, la preparación interior. En cuanto la Oficina de Prensa de la Santa Sede publique el programa y la Conferencia Episcopal Peruana difunda las indicaciones de acceso, esta página se completará con los recintos, los accesos por puerta, los horarios de apertura y el transporte.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (42,11,'llevar','Qué llevar','texto_apartados',30,1,'Equipaje','Qué llevar',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (43,11,'preparar-corazon','Preparar el corazón','texto_lectura',40,1,'Lo importante','Preparar el corazón',NULL,'No se peregrina solo con los pies. Las semanas previas son parte de la visita, y lo que ocurra en ellas se nota el día del encuentro. Vuelve a la oración en familia. Un rato corto y a la misma hora vale más que un propósito largo que no se sostiene. Acércate al sacramento de la reconciliación. Tu parroquia tendrá horarios reforzados conforme se acerquen las fechas. Reconcíliate con quien tengas pendiente. Es lo más difícil de la lista y lo único que no se puede improvisar el día antes. Visita a quien está solo. Un enfermo, un vecino mayor, alguien de la comunidad que ya no puede salir. Muchos ',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (44,11,'mayores-ninos-accesibilidad','Mayores, niños y accesibilidad','texto_lectura',50,1,'Cuidados','Mayores, niños y accesibilidad',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (45,11,'como-llegar-tu','Cómo llegar a tu sede','texto_lectura',60,1,'Transporte','Cómo llegar a tu sede',NULL,'Las indicaciones de acceso, transporte y puntos de encuentro dependen de los recintos, y los recintos todavía no se han anunciado. En cuanto se publiquen, aquí encontrarás para cada sede el punto de acceso, los cortes de tránsito previstos y las rutas recomendadas. Mientras tanto, lo más útil que puedes hacer es preguntar en tu parroquia. Muchas organizan traslado en grupo, y ese suele ser el modo más ordenado de llegar y de volver.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
