INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (49,12,'corre-voz','Corre la voz','texto_lectura',30,1,'Comparte','Corre la voz',NULL,'La mejor difusión de esta visita no la va a hacer una campaña: la van a hacer las parroquias, los colegios y los movimientos contándolo a la gente que tienen al lado. Cuando estén listos, aquí encontrarás un kit sencillo —piezas para redes, un cartel imprimible y un texto breve para leer en las misas dominicales— pensado para que cualquier comunidad pueda usarlo sin saber de diseño. La etiqueta oficial del viaje se anunciará junto con los materiales. Hasta entonces, lo más útil es enlazar directamente a este sitio.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
