INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (56,14,'como-proponer-patrocinio','Cómo proponer un patrocinio','texto_lectura',30,1,'Cómo se hace','Cómo proponer un patrocinio',NULL,'Escribe a la organización contando qué puedes aportar —producto, servicio, horas de trabajo o aporte económico—, en qué sede y en qué fechas. No hace falta un dosier: hace falta una descripción clara. La organización responderá indicando si la necesidad sigue abierta y con qué condiciones. Cada aporte se acredita y se refleja en la rendición de cuentas del viaje. Canal de contacto para patrocinios: [CORREO POR CONFIRMAR].',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
