INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (66,2,'iglesia-peru-te','La Iglesia en el Perú te espera','texto_lectura',100,1,'Conferencia Episcopal Peruana','La Iglesia en el Perú te espera',NULL,'<p>Hay noticias que se reciben con el corazón antes que con la cabeza. La visita del Santo Padre al Perú es una de ellas. El Papa León XIV volverá en noviembre a esta tierra que recorrió durante cuarenta años como misionero, como formador y como obispo. No llega un huésped: vuelve alguien de casa.</p><p>Quienes lo conocieron en Chulucanas, en Trujillo o en Chiclayo saben de qué hablamos. Conoce nuestros caminos de tierra y nuestras parroquias de barrio. Conoce el nombre de nuestras devociones. Conoce lo que cuesta sostener la fe cuando la vida aprieta. Por eso su regreso no es un acontecimiento que ocurra en el Perú: es un acontecimiento del Perú.</p><p>Como pastores de esta Iglesia peregrina queremos pedirte algo sencillo: prepárate. No se trata sólo de conseguir un lugar en una explanada. Se trata de llegar a ese día con el corazón dispuesto. Vuelve a la oración en familia. Acércate al sacramento de la reconciliación. Reconcíliate con quien tengas pendiente. Visita al enfermo del que nadie se acuerda.</p><p>Queremos también que estos días sean obra de todos. Habrá miles de hermanos que necesitarán ser recibidos, orientados, acompañados y cuidados. Para eso nace «Los amigos de León». Si puedes dar tu tiempo, éste es el momento. Da igual tu edad o tu oficio: hay un lugar para cada talento y para cada corazón.</p><p>El lema del Santo Padre, tomado de san Agustín, dice «In Illo uno unum»: aunque los cristianos seamos muchos, en el único Cristo somos uno. Que esas palabras sean también el modo en que preparemos su llegada. Una sola Iglesia en la costa, en la sierra y en la selva. Una sola Iglesia en Lima, en Chiclayo, en Cusco y en Pucallpa.</p><p>Los detalles del programa se irán conociendo a su debido tiempo, y aquí los encontrarás en cuanto sean oficiales. Mientras llega ese momento, te pedimos una oración por el Santo Padre, por su salud y por los frutos de este viaje.</p><p>Que la Virgen María, Madre de la Iglesia, y los santos de nuestra tierra nos acompañen en la preparación.</p><p>Conferencia Episcopal Peruana</p>',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 23:52:50');
