INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (74,17,'como-acreditarse','Cómo acreditarse','texto_lectura',20,1,'Acreditación','Cómo acreditarse',NULL,'En los viajes apostólicos la acreditación de medios la gestiona la Oficina de Prensa de la Santa Sede para el vuelo papal y los actos internacionales, y la conferencia episcopal del país para los actos locales. Los plazos y los formularios se publican con algunas semanas de antelación. En cuanto se abra el proceso, aquí encontrarás el formulario, el plazo de solicitud, los requisitos y los puntos de recogida de credenciales en cada sede.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
