INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (77,18,'responsable-tratamiento','Responsable del tratamiento','texto_lectura',20,1,NULL,'Responsable del tratamiento',NULL,'Este sitio recoge datos personales en tres puntos y en ninguno más: el aviso por correo, el formulario de contacto y la inscripción de voluntariado. No hay analítica, ni píxeles de seguimiento, ni scripts de terceros que recojan datos. Responsable del tratamiento [RAZÓN SOCIAL POR CONFIRMAR], con domicilio en [DOMICILIO POR CONFIRMAR]. Correo para ejercicio de derechos: [CORREO POR CONFIRMAR]. Qué datos y para qué Aviso por correo. Solo tu dirección de correo electrónico, para escribirte cuando se publique aquello de lo que pediste aviso. No se usa para ningún otro envío. Formulario de contact',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (78,19,'cabecera','Cabecera de página','cabecera_pagina',10,1,'Sedes','Cuatro ciudades, un solo pueblo',NULL,'Lima, Chiclayo, Cusco y Pucallpa. La costa, el norte, los Andes y la Amazonía. Cuatro maneras de ser Iglesia en el mismo país.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (79,19,'estas-cuatro','Por qué estas cuatro','texto_lectura',20,1,'Costa, sierra y selva','Por qué estas cuatro',NULL,'La Santa Sede anunció el 5 de agosto de 2026 que el Papa León XIV visitará Lima, Chiclayo, Cusco y Pucallpa entre el 11 y el 16 de noviembre. Es la única información de itinerario que hay: no se ha publicado ni el orden del viaje ni los días que corresponden a cada ciudad. Aun así, la elección dice bastante. Están la capital y su arquidiócesis primada; la diócesis que el Santo Padre pastoreó durante ocho años; la Iglesia andina más antigua del país; y un vicariato apostólico amazónico. Costa, sierra y selva. Una arquidiócesis, una diócesis y un territorio de misión. En esta página encontrarás,',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (80,19,'lima','Lima','texto_lectura',30,1,NULL,'Lima',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (81,19,'cuatro-sedes-mapa','Las cuatro sedes en el mapa del país','texto_lectura',40,1,'Diagrama esquemático','Las cuatro sedes en el mapa del país',NULL,'Del norte costero a los Andes del sur, pasando por la Amazonía central: las cuatro sedes recorren de un extremo a otro las tres regiones del país. Es una geografía que obliga a volar y que explica por qué el viaje ocupa seis días completos.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (82,20,'cabecera','Cabecera de página','cabecera_pagina',10,1,'Rendición de cuentas','Transparencia',NULL,'Quien da algo tiene derecho a saber en qué se usó. Este es el compromiso, escrito antes de recibir el primer aporte.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (83,20,'publicara-cuando','Qué se publicará y cuándo','texto_apartados',20,1,'Compromiso','Qué se publicará y cuándo',NULL,'Todavía no hay nada que rendir: el canal de donativos no está abierto y no se ha recibido ningún aporte a través de este sitio. Lo que sí puede escribirse desde ya es el compromiso.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (84,2,'hero','Carrusel principal','carrusel_hero',5,1,'Visita apostólica','Abramos el corazón',NULL,'Visita Apostólica del Papa León XIV al Perú · 11 al 16 de noviembre de 2026',NULL,NULL,NULL,NULL,'{\"lema\":\"Abramos el corazón\",\"sublema\":\"Visita Apostólica del Papa León XIV al Perú\"}',NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (85,2,'abramos-el-corazon','Bloque «Abramos el corazón»','destacado',15,1,'El lema','Abramos el corazón',NULL,'<p>Una invitación a recibir al Santo Padre, encontrarnos como Iglesia y renovar nuestra esperanza.</p>',NULL,NULL,'Conoce el lema','el-papa/',NULL,NULL,'2026-09-04 23:52:50');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (86,2,'llega-al-peru','El Papa León XIV llega al Perú','destacado',25,1,'La visita','El Papa León XIV llega al Perú',NULL,'<p>Del 11 al 16 de noviembre de 2026, el Santo Padre León XIV realizará su Visita Apostólica al Perú, recorriendo Lima, Chiclayo, Cusco y Pucallpa.</p><p>Su llegada será un tiempo de gracia, encuentro y esperanza para el pueblo peruano, que se prepara para recibirlo con los corazones abiertos.</p>',NULL,NULL,'Conoce la visita','el-papa/',NULL,NULL,'2026-09-04 23:52:50');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (87,2,'el-recorrido','El recorrido · tarjetas de sede','tarjetas_foto',35,1,'El recorrido','Lima · Chiclayo · Cusco · Pucallpa',NULL,'<p>Cuatro ciudades, un solo pueblo. Cada sede tendrá su programa, sus lugares de encuentro y su información para peregrinos.</p>',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (88,2,'tierra-de-santos','Tierra de santos','tarjetas_foto',45,1,'Cinco caminos de santidad','Cinco santos, un mismo corazón',NULL,'<p>El Perú tiene una tradición de santidad que forma parte de la identidad espiritual de su pueblo. Cinco figuras dejaron una huella profunda en la vida de la Iglesia.</p>',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:22');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (89,3,'itinerario','Itinerario del Santo Padre','jornadas',25,1,'El recorrido','El recorrido del Santo Padre',NULL,'<p><strong>Programa referencial.</strong> Las fechas, actividades y lugares serán reemplazados por el programa oficial cuando la Santa Sede lo apruebe y publique.</p>',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:23');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (90,19,'las-cuatro-sedes','Las cuatro sedes','tarjetas_foto',25,1,'Las sedes','Cuatro ciudades, un solo pueblo',NULL,'<p>Cada sede tendrá su programa oficial, sus lugares de encuentro, información para peregrinos, accesos y material multimedia.</p>',NULL,NULL,NULL,NULL,'{\"detalle\": true}',NULL,'2026-09-04 22:17:23');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (91,19,'leon-xiv-y-chiclayo','León XIV y Chiclayo','texto_apartados',35,1,'Un vínculo especial','León XIV y Chiclayo',NULL,'<p>Esta sede merece un tratamiento propio: es el lugar donde el Santo Padre sirvió como obispo entre 2015 y 2023, y donde compartió durante años la vida y la fe de su pueblo.</p>',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:23');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (92,13,'ultimas-noticias','Últimas noticias','noticias',25,1,'Actualidad','Lo más reciente',NULL,'<p>Las informaciones oficiales sobre la Visita Apostólica, publicadas por la Conferencia Episcopal Peruana.</p>',NULL,NULL,NULL,NULL,'{\"detalle\": true}',NULL,'2026-09-04 22:17:23');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (93,5,'sobre-la-cep','Sobre la Conferencia Episcopal','destacado',15,1,'Institucional','Conferencia Episcopal Peruana',NULL,'<p>La Conferencia Episcopal Peruana es la asamblea de los obispos del Perú, que ejercen unidos determinadas funciones pastorales para promover el bien de la Iglesia y de los fieles del país.</p><p>La CEP articula el trabajo de las distintas jurisdicciones eclesiásticas y promueve diversas iniciativas pastorales, sociales, educativas, evangelizadoras y de comunicación.</p>',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:23');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (94,5,'presidencia','Presidencia y autoridades','personas',25,1,'Periodo 2025 – 2028','Presidencia de la CEP',NULL,'<p>Las autoridades de la Conferencia Episcopal Peruana para el periodo 2025–2028.</p>',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:23');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (95,22,'obispos-del-peru','Los obispos del Perú','personas',20,1,'Directorio','Pastores al servicio de la Iglesia y del pueblo peruano',NULL,'<p>La Iglesia Católica en el Perú está presente en todo el territorio nacional a través de sus diferentes jurisdicciones eclesiásticas. Sus arzobispos, obispos y vicarios apostólicos acompañan a las comunidades y desarrollan su misión pastoral en las distintas realidades del país.</p><p><strong>Pendiente:</strong> el directorio completo se cargará con la información oficial de la CEP.</p>',NULL,NULL,NULL,NULL,'{\"detalle\": true}',NULL,'2026-09-04 22:17:23');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (96,5,'mapa-iglesia-peru','Mapa de la Iglesia en el Perú','destacado',45,1,'Una Iglesia presente en todo el territorio','La Iglesia Católica en el Perú',NULL,'<p>El Perú cuenta con <strong>46 jurisdicciones eclesiásticas</strong>: 7 arquidiócesis, 21 diócesis, 10 prelaturas y 8 vicariatos apostólicos.</p><p><strong>Pendiente:</strong> el mapa interactivo requiere la cartografía oficial de la CEP. Las jurisdicciones eclesiásticas no coinciden con los departamentos, así que no puede derivarse de un mapa político.</p>',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:23');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (97,23,'comisiones-episcopales','Las 13 comisiones episcopales','personas',20,1,'13 comisiones al servicio de la Iglesia','Comisiones Episcopales',NULL,'<p>Las Comisiones Episcopales son organismos de servicio de la Conferencia Episcopal Peruana que estudian, apoyan y coordinan determinadas áreas de la pastoral de la Iglesia en el Perú.</p>',NULL,NULL,NULL,NULL,'{\"detalle\": true}',NULL,'2026-09-04 22:17:23');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (98,21,'cabecera','Cabecera de página','cabecera_pagina',10,1,'Cinco caminos de santidad','Tierra de santos',NULL,'Cinco santos, cinco caminos de santidad, un mismo corazón. Sus testimonios acompañan a la Iglesia peruana y pueden iluminar el encuentro del pueblo con el Papa León XIV.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:23');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (99,21,'los-cinco-santos','Los cinco santos','personas',20,1,'Siglos XVI y XVII','Cinco santos, un mismo corazón',NULL,'<p>En los siglos XVI y XVII, cinco figuras dejaron una huella profunda en la vida de la Iglesia. Sus vidas estuvieron marcadas por la oración, la misión, la caridad, la defensa de los más vulnerables y el encuentro con distintas realidades del Perú.</p>',NULL,NULL,NULL,NULL,'{\"detalle\":true}',NULL,'2026-09-04 22:17:23');
