INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (102,17,'notas-de-prensa','Notas de prensa','noticias',35,1,'Comunicados','Notas de prensa',NULL,'<p>Los comunicados oficiales sobre la Visita Apostólica. Cada uno con su fecha y su texto completo.</p>',NULL,NULL,NULL,NULL,'{\"detalle\":true}',NULL,'2026-09-04 22:17:23');
