INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (105,2,'itinerario','El recorrido del Santo Padre','jornadas',37,1,'Del 11 al 16 de noviembre de 2026','El recorrido del Santo Padre',NULL,'<p>El Papa León XIV recorrerá Lima, Chiclayo, Cusco y Pucallpa, llevando su mensaje de esperanza, encuentro y unidad a distintas realidades de la Iglesia y del pueblo peruano.</p>',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 23:52:50');
INSERT INTO `secciones` (`id`, `pagina_id`, `clave`, `nombre`, `plantilla`, `orden`, `activa`, `rotulo`, `titulo`, `subtitulo`, `texto`, `imagen_id`, `imagen_movil_id`, `cta_texto`, `cta_url`, `datos`, `actualizado_por`, `actualizado_en`) VALUES (106,2,'cep-home','Conferencia Episcopal Peruana','personas',95,1,'La Iglesia en el Perú','Conferencia Episcopal Peruana',NULL,'<p>La Conferencia Episcopal Peruana es la asamblea de los obispos del Perú, que ejercen unidos determinadas funciones pastorales para promover el bien de la Iglesia y de los fieles del país.</p><p>La CEP articula el trabajo de las distintas jurisdicciones eclesiásticas y promueve iniciativas pastorales, sociales, educativas, evangelizadoras y de comunicación al servicio de la Iglesia en el Perú.</p>',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 23:52:50');
