INSERT INTO `bloques` (`id`, `seccion_id`, `orden`, `activo`, `rotulo`, `titulo`, `slug`, `texto`, `icono`, `imagen_id`, `imagen_movil_id`, `enlace_texto`, `enlace_url`, `datos`, `creado_en`, `actualizado_en`) VALUES (114,89,60,1,'16 de noviembre','Lima · Hasta pronto, Perú',NULL,'Despedida y salida del Perú.',NULL,NULL,NULL,'Revive la visita','#','{\"actividades\":[\"Encuentro de despedida\",\"Mensaje final del Santo Padre\",\"Ceremonia de despedida\",\"Salida del Perú\"]}','2026-09-04 22:17:23','2026-09-04 22:17:23');
INSERT INTO `bloques` (`id`, `seccion_id`, `orden`, `activo`, `rotulo`, `titulo`, `slug`, `texto`, `icono`, `imagen_id`, `imagen_movil_id`, `enlace_texto`, `enlace_url`, `datos`, `creado_en`, `actualizado_en`) VALUES (115,90,10,1,'Arquidiócesis de Lima','Lima','lima','<p>Lima será la puerta de entrada de la Visita Apostólica del Papa León XIV al Perú y uno de los espacios de encuentro del Santo Padre con la Iglesia y el pueblo peruano.</p><p><em>Esta página quedará preparada para incorporar el programa oficial, los lugares de encuentro, la información para peregrinos, los accesos, las noticias y el material multimedia.</em></p>',NULL,NULL,NULL,'Conoce Lima','sedes/lima/','{\"resumen\": \"Lima será la puerta de entrada de la Visita Apostólica y uno de los espacios de encuentro del Santo Padre con la Iglesia y el pueblo peruano.\"}','2026-09-04 22:17:23','2026-09-04 22:17:23');
INSERT INTO `bloques` (`id`, `seccion_id`, `orden`, `activo`, `rotulo`, `titulo`, `slug`, `texto`, `icono`, `imagen_id`, `imagen_movil_id`, `enlace_texto`, `enlace_url`, `datos`, `creado_en`, `actualizado_en`) VALUES (116,90,20,1,'Diócesis de Chiclayo','Chiclayo','chiclayo','<p>Chiclayo ocupa un lugar especial en la historia pastoral del Papa León XIV. En esta tierra, el Santo Padre sirvió como obispo entre 2015 y 2023 y compartió durante años la vida y la fe de su pueblo.</p><p>Por ese vínculo, esta sede tendrá un módulo propio —«León XIV y Chiclayo»— con fotografías históricas, testimonios y momentos de su ministerio episcopal.</p><p><em>Pendiente de recibir el material gráfico de la diócesis.</em></p>',NULL,NULL,NULL,'Conoce Chiclayo','sedes/chiclayo/','{\"resumen\": \"Chiclayo ocupa un lugar especial en la historia pastoral del Papa León XIV.\"}','2026-09-04 22:17:23','2026-09-04 22:17:23');
INSERT INTO `bloques` (`id`, `seccion_id`, `orden`, `activo`, `rotulo`, `titulo`, `slug`, `texto`, `icono`, `imagen_id`, `imagen_movil_id`, `enlace_texto`, `enlace_url`, `datos`, `creado_en`, `actualizado_en`) VALUES (117,90,30,1,'Arquidiócesis del Cusco','Cusco','cusco','<p>Cusco se presenta desde su profunda identidad andina, cultural y religiosa, y no como una postal turística. La Iglesia andina más antigua del país acogerá al Santo Padre en una jornada centrada en la comunidad, los jóvenes y las familias.</p><p><em>Esta página incorporará las actividades del Papa, los lugares de encuentro, las indicaciones para peregrinos y los contenidos propios de la Arquidiócesis.</em></p>',NULL,NULL,NULL,'Conoce Cusco','sedes/cusco/','{\"resumen\": \"Cusco se presenta desde su profunda identidad andina, cultural y religiosa.\"}','2026-09-04 22:17:23','2026-09-04 22:17:23');
INSERT INTO `bloques` (`id`, `seccion_id`, `orden`, `activo`, `rotulo`, `titulo`, `slug`, `texto`, `icono`, `imagen_id`, `imagen_movil_id`, `enlace_texto`, `enlace_url`, `datos`, `creado_en`, `actualizado_en`) VALUES (118,90,40,1,'Vicariato de Pucallpa','Pucallpa','pucallpa','<p>El encuentro con la Amazonía, sus comunidades y los pueblos originarios. Una jornada centrada en el cuidado de la casa común y en la realidad de la Iglesia amazónica.</p><p><em>Esta página incorporará las actividades oficiales, las comunidades participantes, los lugares de encuentro, los accesos y los contenidos multimedia.</em></p>',NULL,NULL,NULL,'Conoce Pucallpa','sedes/pucallpa/','{\"resumen\": \"El encuentro con la Amazonía, sus comunidades y los pueblos originarios.\"}','2026-09-04 22:17:23','2026-09-04 22:17:23');
