INSERT INTO `bloques` (`id`, `seccion_id`, `orden`, `activo`, `rotulo`, `titulo`, `slug`, `texto`, `icono`, `imagen_id`, `imagen_movil_id`, `enlace_texto`, `enlace_url`, `datos`, `creado_en`, `actualizado_en`) VALUES (143,97,130,1,'Mons. Guillermo Monzón · Obispo Auxiliar de Lima','Cáritas del Perú','caritas-del-peru','Acción caritativa y social, atención a poblaciones vulnerables y desarrollo humano integral.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 22:17:23','2026-09-04 22:17:23');
INSERT INTO `bloques` (`id`, `seccion_id`, `orden`, `activo`, `rotulo`, `titulo`, `slug`, `texto`, `icono`, `imagen_id`, `imagen_movil_id`, `enlace_texto`, `enlace_url`, `datos`, `creado_en`, `actualizado_en`) VALUES (144,99,10,1,'Oración · Entrega · Servicio','Santa Rosa de Lima','santa-rosa-de-lima','<p>Isabel Flores de Oliva, conocida como Santa Rosa de Lima, nació en Lima en 1586 y dedicó su vida a Dios desde una profunda experiencia de oración y entrega. Vivió como laica consagrada y perteneció a la Tercera Orden de Santo Domingo.</p><p>En medio de una vida sencilla, hizo del servicio a los pobres y enfermos una expresión concreta de su amor a Dios. Atendía a personas necesitadas y convirtió parte de su propia casa en un espacio de acogida para quienes sufrían.</p><p>Murió en Lima en 1617, a los 31 años. Fue canonizada por el papa Clemente X el 12 de abril de 1671, convirtiéndose en la primera santa de América. Es patrona del Perú, de América y de Filipinas.</p>',NULL,NULL,NULL,NULL,NULL,'{\"anios\":\"1586 – 1617\",\"resumen\":\"Una vida entregada a Dios y al servicio de los más necesitados.\"}','2026-09-04 22:17:23','2026-09-04 22:17:23');
INSERT INTO `bloques` (`id`, `seccion_id`, `orden`, `activo`, `rotulo`, `titulo`, `slug`, `texto`, `icono`, `imagen_id`, `imagen_movil_id`, `enlace_texto`, `enlace_url`, `datos`, `creado_en`, `actualizado_en`) VALUES (145,99,20,1,'Caridad · Humildad · Fraternidad','San Martín de Porres','san-martin-de-porres','<p>Martín de Porres nació en Lima en 1579. Creció en una sociedad marcada por profundas diferencias sociales y raciales, y desde joven mostró una especial sensibilidad hacia los pobres y enfermos.</p><p>Ingresó al Convento del Santísimo Rosario de los dominicos de Lima, donde desarrolló diferentes labores de servicio antes de convertirse en fraile. Su servicio no hizo distinciones: atendía a personas de todas las condiciones y manifestó un especial amor por los animales y por toda la creación.</p><p>La tradición lo recuerda como el «Santo de la escoba», imagen que expresa su humildad. Fue canonizado por el papa Juan XXIII el 6 de mayo de 1962.</p>',NULL,NULL,NULL,NULL,NULL,'{\"anios\":\"1579 – 1639\",\"resumen\":\"Hizo del servicio humilde un camino de santidad.\"}','2026-09-04 22:17:23','2026-09-04 22:17:23');
INSERT INTO `bloques` (`id`, `seccion_id`, `orden`, `activo`, `rotulo`, `titulo`, `slug`, `texto`, `icono`, `imagen_id`, `imagen_movil_id`, `enlace_texto`, `enlace_url`, `datos`, `creado_en`, `actualizado_en`) VALUES (146,99,30,1,'Misericordia · Servicio · Solidaridad','San Juan Macías','san-juan-macias','<p>Juan Macías nació en Ribera del Fresno, España, en 1585. Huérfano desde muy joven, trabajó como pastor antes de emigrar a América. Llegó al Perú y se estableció en Lima, donde ingresó a la Orden de Predicadores.</p><p>Durante más de dos décadas fue hermano portero del convento dominico de La Magdalena. Desde ese lugar desarrolló una intensa labor de ayuda a los pobres: su servicio comenzaba en la puerta del convento y se extendía mediante la distribución de alimentos y limosnas.</p><p>Su amistad con San Martín de Porres es otro elemento importante de la historia de la santidad limeña. Fue canonizado por Pablo VI el 28 de septiembre de 1975.</p>',NULL,NULL,NULL,NULL,NULL,'{\"anios\":\"1585 – 1645\",\"resumen\":\"Desde la sencillez, hizo de la misericordia una forma de vida.\"}','2026-09-04 22:17:23','2026-09-04 22:17:23');
INSERT INTO `bloques` (`id`, `seccion_id`, `orden`, `activo`, `rotulo`, `titulo`, `slug`, `texto`, `icono`, `imagen_id`, `imagen_movil_id`, `enlace_texto`, `enlace_url`, `datos`, `creado_en`, `actualizado_en`) VALUES (147,99,40,1,'Misión · Encuentro · Evangelización','San Francisco Solano','san-francisco-solano','<p>Francisco Solano nació en Montilla, España, en 1549. Ingresó a la Orden Franciscana y fue ordenado sacerdote en 1576. Llegó a América en 1589 y desembarcó en Paita, Piura.</p><p>Desde allí emprendió un largo recorrido por territorios del actual Perú y otros países de Sudamérica. Aprendió lenguas indígenas para comunicarse con los pueblos a los que servía y utilizó también la música como instrumento de evangelización.</p><p>Su vida se vincula especialmente con la idea de una Iglesia en salida: caminar, encontrarse con las personas y llevar el Evangelio allí donde se encuentran. Murió en Lima el 14 de julio de 1610.</p>',NULL,NULL,NULL,NULL,NULL,'{\"anios\":\"1549 – 1610\",\"resumen\":\"Caminó grandes distancias para llevar el Evangelio al encuentro de los pueblos.\"}','2026-09-04 22:17:23','2026-09-04 22:17:23');
INSERT INTO `bloques` (`id`, `seccion_id`, `orden`, `activo`, `rotulo`, `titulo`, `slug`, `texto`, `icono`, `imagen_id`, `imagen_movil_id`, `enlace_texto`, `enlace_url`, `datos`, `creado_en`, `actualizado_en`) VALUES (148,99,50,1,'Pastor · Misión · Defensa de los pueblos','Santo Toribio de Mogrovejo','santo-toribio-de-mogrovejo','<p>Toribio Alfonso de Mogrovejo nació en Mayorga, España, en 1538. Estudió Derecho y fue profesor en la Universidad de Salamanca, hasta que fue elegido para asumir el Arzobispado de Lima. Llegó al Perú en 1581.</p><p>Concibió su ministerio como una misión que exigía salir al encuentro de las comunidades. Recorrió extensas regiones del territorio peruano, aprendió quechua y promovió la evangelización en lenguas nativas. Participó decisivamente en el III Concilio Limense.</p><p>Destacó por la defensa de los pueblos indígenas frente a abusos. Murió en Zaña en 1606 y fue canonizado en 1726: en 2026 se conmemoran <strong>300 años de su canonización</strong>, algo que el propio Santo Padre destacó en su encuentro con los obispos del Perú en enero de 2026.</p>',NULL,NULL,NULL,NULL,NULL,'{\"anios\":\"1538 – 1606\",\"resumen\":\"Un pastor en salida que recorrió el Perú para anunciar el Evangelio y acompañar a su pueblo.\"}','2026-09-04 22:17:23','2026-09-04 22:17:23');
INSERT INTO `bloques` (`id`, `seccion_id`, `orden`, `activo`, `rotulo`, `titulo`, `slug`, `texto`, `icono`, `imagen_id`, `imagen_movil_id`, `enlace_texto`, `enlace_url`, `datos`, `creado_en`, `actualizado_en`) VALUES (149,57,10,1,'Peregrinos','Guía del peregrino',NULL,'Qué llevar, cómo llegar y qué esperar de cada celebración. Se publicará junto con el programa oficial.',NULL,NULL,NULL,'Ver más','guia-del-peregrino/',NULL,'2026-09-04 23:52:50','2026-09-04 23:52:50');
