-- ===========================================================================
--  03 · CONTENIDO · lo que se ve en la web
-- ---------------------------------------------------------------------------
--  Las 24 páginas del sitio con sus 105 secciones y sus 85 fichas, tal como
--  están en producción: el carrusel de la portada, el itinerario, las cuatro
--  sedes, los cinco santos, las noticias, los obispos y las trece comisiones.
--
--  También los 19 ajustes generales —las fechas del viaje, la página de
--  inicio, el menú— y los dos comunicados.
--
--  ── Lo que NO se siembra, y por qué ──────────────────────────────────────
--
--  La biblioteca de imágenes (`medios`) se queda vacía. En producción tiene
--  una sola fila, apuntando a un archivo de assets/subidos/ que no está en el
--  repositorio —las subidas del panel no se versionan— y que no usa ninguna
--  sección ni ninguna ficha. Sembrarla sólo dejaría una imagen rota.
--
--  Las páginas y las fichas se ven igual: cada una lleva su fotografía de
--  respaldo escrita en la vista. Cuando subas imágenes desde el panel, esas
--  sustituyen al respaldo.
--
--  ── Con qué versiones está probado ───────────────────────────────────────
--
--    Producción      MariaDB 11.8.6  ·  PHP 8.3  ·  Nginx
--    Desarrollo      MariaDB 10.4    ·  PHP 8.1  ·  Apache (XAMPP)
--
--    Mínimo          MariaDB 10.4    ·  PHP 8.0
--
--  MariaDB, NO MySQL. Tres migraciones del proyecto usan
--  «ADD COLUMN IF NOT EXISTS», que MySQL no acepta. Y este archivo se generó
--  con el cliente de MariaDB 10.4 a propósito: así usa la sintaxis más
--  conservadora y entra igual en 10.4 que en 11.8.
-- ===========================================================================

SET NAMES utf8mb4;


-- Los dos comunicados entran APAGADOS.
--
-- Su cartel se subió desde el panel y vive en assets/subidos/, que no se
-- versiona. Activos, la portada pediría una imagen que no existe y el
-- primer arranque saldría con un 404 en la consola.
--
-- Se ven igual en el panel; para probarlos, sube un cartel y enciéndelos.
UPDATE `comunicados` SET `activo` = 0, `imagen` = NULL;
